import { Component, OnInit } from '@angular/core';
import { Title } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { getConfig } from 'src/app/app-config';
import { AppConstants } from '../../constants/app.constants';
import { FormConfig } from '../../service/form-config';
import { FormService } from '../../service/form.service';
import {AuthService} from '../../auth/auth.service';

declare var $: any;

@Component({
  selector: 'app-start-payment',
  templateUrl: './start-payment.component.html',
  styleUrls: ['./start-payment.component.scss']
})
export class StartPaymentComponent implements OnInit {

  pdfurl: string = '';
  uuid: string = '';
  amount = 0;
  formTitle: string = '';
  reference: string = '';
  appId = '';
  payment = null;
  secured = false;
  showPaymentDetails = false;
  showReturnButton = false;

  constructor(public route: ActivatedRoute,
              private titleService: Title,
              private router: Router,
              private formService: FormService,
              private authService: AuthService
              ) {
    this.route.queryParams
        .subscribe(params => {
          this.uuid = params.uuid;
          this.amount = params.amount;
          this.reference = params.reference;
          this.formTitle = params.formTitle
        });
  }

  ngOnInit(): void {
    this.titleService.setTitle(AppConstants.TITLE_PREFIX + 'Start betaling');
    if (!this.uuid){
      this.router.navigateByUrl('error');
    }

    this.secured = this.authService.isAuthenticated();
    this.findDraftPayment();
    this.pdfurl = this.formService.getPdfUrl(this.secured, this.uuid, this.reference, this.formTitle)
  }

  public openPDF(pdfUrl: string): void {
    window.open(pdfUrl);
  }

  public currencyFormat(): string {
    return (
        this.amount
            .toFixed(2) // always two decimal digits
            .replace('.', ',') // replace decimal point character with ,
            .replace(/(\d)(?=(\d{3})+(?!\d))/g, '$1.')
    ); // use . as a separator
  }

  public findDraftPayment(): void{
    $('#overlay').fadeIn();
    this.formService.findDraftPayment(this.uuid).subscribe(result => {
      $('#overlay').fadeOut();
      if (result){
        this.uuid = result.uuid;
        this.amount = result.amount;
        this.formTitle = result.formTitle;
        this.reference = result.reference;
        this.appId = result.appId;
        this.payment = result.payment;
        this.secured = result.secured;

        this.showPaymentDetails = true;

        this.startPayment();
      }else{
        // nothing was found
        this.showReturnButton = true;
      }
    });
  }

  startPayment(): void {
    $('#overlay').fadeIn().delay(10000).fadeOut();
    this.formService.doPayment(this.amount, this.uuid, this.reference, this.formTitle, false, this.payment);

  }

  getCallbackUrl(): string {
    return this.formService.getCallbackUrl();
  }

}
