import {Injectable} from '@angular/core';
import {ActivatedRouteSnapshot, CanActivate, Router, RouterStateSnapshot} from '@angular/router';
import {AuthService} from './auth.service';
import {AppConstants} from '../constants/app.constants';
import {Observable, of} from 'rxjs';
import {catchError, map} from 'rxjs/operators';
import {FormService} from '../service/form.service';

@Injectable({
    providedIn: 'root'
})
export class AuthGuard implements CanActivate {

    constructor(private readonly authService: AuthService,
                private readonly formService: FormService,
                private router: Router) {
    }

    async canActivate(
        route: ActivatedRouteSnapshot,
        state: RouterStateSnapshot) {

        // check if token is not available or expired remove the local user data
        /*if (!this.authService.isAuthenticated()) {
            this.authService.removeLocalUserdata();
        }*/

        // need to see determine which loginTypes need authentication

        const result = await this.formService.findFormConfig(route.params.formName).toPromise();
        if (result) {
            localStorage.setItem(AppConstants.FORM_CONFIG, JSON.stringify(result));
            if (result.loginTypes.length === 0){
                // anonymous form
                return true;
            }

            if (this.authService.isAuthenticated()) {
                // is already authenticated, load userprofile to get userdata specific for the form.
                this.authService.loadUserProfile();
                return true;
            }

            // we need to login, so store the url in localstorage
            localStorage.setItem(AppConstants.REDIRECT_URL, state.url);
            // next call the external authentication service
            this.authService.login(route.params.formName);
            return false;
        } else {
            // no Form config found
            return this.router.parseUrl('error');
        }
    }
}
